const $ = (id) => document.getElementById(id);
let currentPart = "A";
let currentVersion = "1";
let currentIndex = 0;
let candidate = "";
let responses = {};
let latestSubmission = null;

function responseKey(part, index){ return `${currentVersion}-${part}-${index}`; }
function render(){
  const rows = QUESTION_BANK[currentVersion];
  const item = rows[currentIndex];
  $("candidateLabel").textContent = `${candidate} · VERSION ${currentVersion}`;
  $("partTitle").textContent = currentPart === "A" ? "Part A — Open-ended questions" : "Part B — Multiple-choice questions";
  $("progressText").textContent = `Question ${currentIndex+1} of 20`;
  $("progressBar").style.width = `${(currentIndex+1)*5}%`;
  const host = $("questionList");
  host.innerHTML = "";
  const card = document.createElement("article");
  card.className = "question-card";
  const meta = document.createElement("div");
  meta.className = "question-meta";
  meta.innerHTML = `<span class="q-number">QUESTION ${currentIndex+1} OF 20</span><span class="level">${item.level}</span><span class="level">${item.topic}</span>`;
  card.appendChild(meta);
  const q = document.createElement("p");
  q.className = "question-text";
  q.textContent = currentPart === "A" ? item.open : item.mcq;
  card.appendChild(q);
  const key = responseKey(currentPart, currentIndex);
  if(currentPart === "A"){
    const area = document.createElement("textarea");
    area.placeholder = "Write your answer here…";
    area.value = responses[key] || "";
    area.addEventListener("input", () => responses[key] = area.value);
    card.appendChild(area);
  } else {
    item.options.forEach((option, i) => {
      const label = document.createElement("label");
      label.className = "choice";
      const radio = document.createElement("input");
      radio.type = "radio"; radio.name = "mcq"; radio.value = String(i);
      radio.checked = responses[key] === String(i);
      radio.addEventListener("change", () => responses[key] = String(i));
      const span = document.createElement("span");
      span.textContent = `${String.fromCharCode(65+i)}. ${option}`;
      label.append(radio, span); card.appendChild(label);
    });
  }
  host.appendChild(card);
  $("backBtn").hidden = !(currentPart === "B" && currentIndex === 0);
  $("nextBtn").textContent = currentPart === "A"
    ? (currentIndex === 19 ? "Continue to Part B" : "Next question")
    : (currentIndex === 19 ? "Submit assessment" : "Next question");
}
function begin(){
  candidate = $("candidateName").value.trim();
  if(!candidate){ alert("Please enter the candidate name."); $("candidateName").focus(); return; }
  currentVersion = $("versionSelect").value;
  currentPart = "A"; currentIndex = 0; responses = {};
  $("setup").hidden = true; $("assessment").hidden = false; $("submitted").hidden = true;
  render(); window.scrollTo({top:0,behavior:"smooth"});
}
function next(){
  if(currentIndex < 19){ currentIndex++; render(); window.scrollTo({top:0,behavior:"smooth"}); return; }
  if(currentPart === "A"){ currentPart = "B"; currentIndex = 0; render(); window.scrollTo({top:0,behavior:"smooth"}); return; }
  submit();
}
function submit(){
  const rows = QUESTION_BANK[currentVersion];
  latestSubmission = {
    assessment: "IICS Technical Assessment",
    candidate,
    version: Number(currentVersion),
    submittedAt: new Date().toISOString(),
    note: "Candidate responses only. This project contains no answer key and performs no grading.",
    partA: rows.map((q,i)=>({number:i+1,difficulty:q.level,topic:q.topic,question:q.open,response:responses[responseKey("A",i)] || ""})),
    partB: rows.map((q,i)=>({number:i+1,difficulty:q.level,topic:q.topic,question:q.mcq,options:q.options,selectedOption:responses[responseKey("B",i)] === undefined ? null : Number(responses[responseKey("B",i)])}))
  };
  $("assessment").hidden = true; $("submitted").hidden = false;
  $("submissionSummary").innerHTML = `<strong>${escapeHtml(candidate)}</strong><span>Version ${currentVersion}</span><span>20 open-ended responses and 20 multiple-choice responses included.</span>`;
  window.scrollTo({top:0,behavior:"smooth"});
}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function download(){
  const blob = new Blob([JSON.stringify(latestSubmission,null,2)],{type:"application/json"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = `IICS_Assessment_V${currentVersion}_${candidate.replace(/[^a-z0-9_-]+/gi,"_")}.json`;
  document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
}
$("startBtn").addEventListener("click",begin);
$("nextBtn").addEventListener("click",next);
$("backBtn").addEventListener("click",()=>{currentPart="A";currentIndex=19;render();window.scrollTo({top:0,behavior:"smooth"});});
$("downloadBtn").addEventListener("click",download);
$("printBtn").addEventListener("click",()=>window.print());
